import React, { useEffect, useState } from "react";
import "./App.css";

const API = "http://127.0.0.1:8000/products";

function App() {
  const [products, setProducts] = useState([]);
  const [form, setForm] = useState({
    id: "",
    name: "",
    description: "",
    price: "",
    quantity: "",
  });
  const [editingId, setEditingId] = useState(null);

  // Load all products
  const loadProducts = async () => {
    try {
      const res = await fetch(API);
      const data = await res.json();
      setProducts(data);
    } catch (err) {
      console.log("Error:", err);
    }
  };

  useEffect(() => {
    loadProducts();
  }, []);

  // Handle form input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // Add product
  const addProduct = async () => {
    await fetch(API, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });
    setForm({ id: "", name: "", description: "", price: "", quantity: "" });
    loadProducts();
  };

  // Delete product
  const deleteProduct = async (id) => {
    await fetch(`${API}/${id}`, { method: "DELETE" });
    loadProducts();
  };

  // Start editing
  const startEdit = (p) => {
    setEditingId(p.id);
    setForm(p);
  };

  // Save updated product
  const saveEdit = async () => {
    await fetch(`${API}/${editingId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(form),
    });

    setEditingId(null);
    setForm({ id: "", name: "", description: "", price: "", quantity: "" });
    loadProducts();
  };

  return (
    <div className="container">
      <h1>FastAPI + React CRUD</h1>

      {/* Add / Edit Form */}
      <div className="card">
        <h2>{editingId ? "Edit Product" : "Add Product"}</h2>

        <input name="id" placeholder="ID" value={form.id} onChange={handleChange} disabled={editingId !== null} />

        <input name="name" placeholder="Name" value={form.name} onChange={handleChange} />
        <input name="description" placeholder="Description" value={form.description} onChange={handleChange} />
        <input name="price" placeholder="Price" value={form.price} onChange={handleChange} />
        <input name="quantity" placeholder="Quantity" value={form.quantity} onChange={handleChange} />

        {editingId ? (
          <>
            <button className="btn-save" onClick={saveEdit}>Save</button>
            <button className="btn-cancel" onClick={() => setEditingId(null)}>Cancel</button>
          </>
        ) : (
          <button className="btn-add" onClick={addProduct}>Add</button>
        )}
      </div>

      {/* Product List */}
      <div className="card">
        <h2>Products</h2>

        <table>
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Description</th>
              <th>Price</th>
              <th>Qty</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {products.map((p) => (
              <tr key={p.id}>
                <td>{p.id}</td>
                <td>{p.name}</td>
                <td>{p.description}</td>
                <td>{p.price}</td>
                <td>{p.quantity}</td>
                <td>
                  <button className="btn-edit" onClick={() => startEdit(p)}>Edit</button>
                  <button className="btn-delete" onClick={() => deleteProduct(p.id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>

        </table>
      </div>
    </div>
  );
}
